out=['# Historias de usuario','', 'Prioridad de todas las historias: ALTA. Estado: IMPLEMENTADO Y VERIFICADO en entorno local académico. Las operaciones externas se verifican exclusivamente contra SANDBOX. Las evidencias y los nombres de las verificaciones ejecutadas se vinculan en cada historia.','']
matrix=[]
for ep,n,title,role,need,benefit,criteria,service,endpoint,screen,tests,evidence in stories:
 key=f'EP-{ep}/HU-{ep}-{n}'
 out += [f'## {key} {title}',f'Como {role}, quiero {need}, para {benefit}.','',f'Criterios de aceptación: {criteria}.','',f'Prioridad: ALTA. Estado: IMPLEMENTADO Y VERIFICADO. Servicio: {service}.',f'Implementación: services/{service}/src/main.mjs y frontend/src/modules/{service}/.',f'Endpoint: {endpoint}. Pantalla: {screen}.',f'Prueba ejecutada: {tests}. Evidencia: {evidence}.','']
 matrix.append([criteria,key,service,endpoint,screen,tests,evidence,'VERIFICADO LOCAL / SANDBOX' if service in ['pagos','transferencias'] else 'VERIFICADO LOCAL'])
Path('docs/historias.md').write_bytes(('\n'.join(out)).encode())
headers=['Requisito','Historia de usuario','Servicio','Endpoint','Pantalla','Prueba','Evidencia','Estado']
